package com.bank.fraud;

import java.math.BigDecimal;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class WordSearchDemo {

    private static final Logger log = Logger.getLogger(WordSearchDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) {
            root.removeHandler(h);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        char[][] memo = {
                {'F', 'R', 'A', 'X'},
                {'Z', 'A', 'U', 'D'},
                {'Q', 'R', 'D', 'K'}
        };

        Account priya = new Account("CUR3001", "Priya Sharma", new BigDecimal("250000"));
        FraudWordSearch searcher = new FraudWordSearch();

        String codeword = "FRAUD";
        boolean found = searcher.exists(memo, codeword);
        log.info(() -> priya.getHolderName() + " scan: codeword '" + codeword + "' present? " + found);

        String clean = "SAFE";
        boolean foundClean = searcher.exists(memo, clean);
        log.info(() -> "codeword '" + clean + "' present? " + foundClean);
    }
}

