class FraudWordSearch {

    private static final Logger log = Logger.getLogger(FraudWordSearch.class.getName());

    // Returns true if word can be traced as a connected path of adjacent cells.
    boolean exists(char[][] board, String word) {
        if (board == null || board.length == 0 || word == null || word.isEmpty()) {
            return false;
        }
        for (int i = 0; i < board.length; i++) {
            for (int j = 0; j < board[0].length; j++) {
                if (dfs(board, word, i, j, 0)) {
                    return true;
                }
            }
        }
        return false;
    }

    private boolean dfs(char[][] board, String word, int row, int col, int index) {
        if (index == word.length()) {
            return true;                       // matched every character
        }
        if (row < 0 || row >= board.length || col < 0 || col >= board[0].length) {
            return false;                      // out of bounds
        }
        if (board[row][col] != word.charAt(index)) {
            return false;                      // character mismatch or already used (sentinel)
        }

        char original = board[row][col];
        board[row][col] = '#';                 // mark visited for this path
        log.fine(() -> "enter [" + row + "][" + col + "] matching '" + word.charAt(index) + "'");

        boolean found = dfs(board, word, row + 1, col, index + 1)
                || dfs(board, word, row - 1, col, index + 1)
                || dfs(board, word, row, col + 1, index + 1)
                || dfs(board, word, row, col - 1, index + 1);

        board[row][col] = original;            // backtrack: restore cell
        return found;
    }
}

